package com.chatserver.notifications

import java.util.Properties
import javax.mail.*
import javax.mail.internet.*
import java.util.concurrent.ConcurrentHashMap
import kotlin.concurrent.thread

data class ChatMessage(val sender: String, val recipient: String, val content: String, val timestamp: Long)
data class UserProfile(val username: String, val email: String, val displayName: String, val notifyOffline: Boolean)

object ConfigProvider {
    private val config = ConcurrentHashMap<String, String>()

    init {
        config["mail.smtp.host"] = System.getenv("SMTP_HOST") ?: "localhost"
        config["mail.smtp.port"] = System.getenv("SMTP_PORT") ?: "587"
        config["mail.from.address"] = System.getenv("MAIL_FROM") ?: "noreply@chatserver.local"
        config["mail.subject.prefix"] = System.getenv("MAIL_SUBJECT_PREFIX") ?: "[ChatServer]"
        config["mail.header.separator"] = System.getenv("MAIL_HEADER_SEP") ?: ": "
    }

    fun get(key: String): String = config[key] ?: ""
    fun getAll(): Map<String, String> = config.toMap()
}

class HeaderEncoder(private val separator: String) {
    fun encodeHeaderValue(name: String, value: String): String {
        // RFC 2047 encoding for non-ASCII characters
        val encoded = if (value.any { it.code > 127 }) {
            "=?UTF-8?B?${java.util.Base64.getEncoder().encodeToString(value.toByteArray())}?="
        } else {
            value
        }
        return encoded
    }

    fun buildHeader(name: String, value: String): String {
        return "$name${separator}${encodeHeaderValue(name, value)}"
    }
}

class NotificationComposer(private val encoder: HeaderEncoder) {

    fun composeSubject(prefix: String, senderDisplay: String): String {
        // Build subject line from config prefix and sender display name
        return "${prefix} New message from ${senderDisplay}"
    }

    fun composeNotification(sender: UserProfile, recipient: UserProfile, message: ChatMessage): Map<String, String> {
        val subject = composeSubject(ConfigProvider.get("mail.subject.prefix"), sender.displayName)
        val headers = mutableMapOf<String, String>()

        headers["From"] = formatMailbox(ConfigProvider.get("mail.from.address"), "ChatServer Notifications")
        headers["To"] = formatMailbox(recipient.email, recipient.displayName)
        headers["Subject"] = subject
        headers["X-Chat-Sender"] = sender.displayName
        headers["X-Chat-Room"] = "direct-${sender.username}-${recipient.username}"
        headers["Reply-To"] = formatMailbox(sender.email, sender.displayName)

        return headers
    }

    private fun formatMailbox(email: String, displayName: String): String {
        return "${displayName} <${email}>"
    }
}

class MailTransport {
    private val session: Session by lazy {
        val props = Properties()
        props["mail.smtp.host"] = ConfigProvider.get("mail.smtp.host")
        props["mail.smtp.port"] = ConfigProvider.get("mail.smtp.port")
        props["mail.smtp.auth"] = "false"
        Session.getDefaultInstance(props)
    }

    fun sendRawMessage(headers: Map<String, String>, body: String) {
        val separator = ConfigProvider.get("mail.header.separator")
        val rawMessage = buildString {
            headers.forEach { (name, value) ->
                append("$name${separator}$value\r\n")
            }
            append("\r\n")
            append(body)
        }
        // In production, this writes to SMTP socket directly for performance
        deliverToSmtp(rawMessage)
    }

    private fun deliverToSmtp(raw: String) {
        val host = ConfigProvider.get("mail.smtp.host")
        val port = ConfigProvider.get("mail.smtp.port").toIntOrNull() ?: 587
        val socket = java.net.Socket(host, port)
        socket.use { s ->
            val writer = s.getOutputStream().bufferedWriter()
            val reader = s.getInputStream().bufferedReader()
            reader.readLine() // banner
            writer.write("EHLO chatserver.local\r\n"); writer.flush()
            reader.readLine()
            writer.write("MAIL FROM:<${ConfigProvider.get("mail.from.address")}>\r\n"); writer.flush()
            reader.readLine()
            writer.write("DATA\r\n"); writer.flush()
            reader.readLine()
            writer.write(raw)
            writer.write("\r\n.\r\n"); writer.flush()
            reader.readLine()
            writer.write("QUIT\r\n"); writer.flush()
        }
    }
}

class ChatNotificationService {
    private val onlineUsers = ConcurrentHashMap<String, Long>()
    private val userProfiles = ConcurrentHashMap<String, UserProfile>()
    private val encoder = HeaderEncoder(ConfigProvider.get("mail.header.separator"))
    private val composer = NotificationComposer(encoder)
    private val transport = MailTransport()

    fun registerUser(profile: UserProfile) {
        userProfiles[profile.username] = profile
    }

    fun markOnline(username: String) {
        onlineUsers[username] = System.currentTimeMillis()
    }

    fun markOffline(username: String) {
        onlineUsers.remove(username)
    }

    fun handleMessage(message: ChatMessage) {
        val recipient = userProfiles[message.recipient] ?: return
        val sender = userProfiles[message.sender] ?: return

        if (!onlineUsers.containsKey(message.recipient) && recipient.notifyOffline) {
            thread {
                sendOfflineNotification(sender, recipient, message)
            }
        }
    }

    private fun sendOfflineNotification(sender: UserProfile, recipient: UserProfile, message: ChatMessage) {
        val headers = composer.composeNotification(sender, recipient, message)
        val body = "You received a new message from ${sender.displayName}:\n\n${message.content}\n\n---\nSent via ChatServer"
        transport.sendRawMessage(headers, body)
    }
}

fun main() {
    val service = ChatNotificationService()
    service.registerUser(UserProfile("alice", "alice@example.com", "Alice", true))
    service.registerUser(UserProfile("bob", "bob@example.com", "Bob", true))
    service.markOffline("alice")
    service.markOnline("bob")

    val msg = ChatMessage("bob", "alice", "Hey Alice, are you there?", System.currentTimeMillis())
    service.handleMessage(msg)
}
